package village.naruto.health;
import java.lang.reflect.*;
import java.util.*;
import org.bukkit.*;
import org.bukkit.attribute.*;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import org.bukkit.event.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;
/** Original server-only adapter. Native Ninja XP is read, never assigned. */
public final class NinjaHealth extends JavaPlugin implements Listener {
 private static final UUID NATIVE=UUID.fromString("84d6711b-c26d-4dfa-b0c5-1ff54395f4de");
 private static final UUID BONUS=UUID.fromString("a3175a00-6d54-4e6c-a620-6cf370862d17");
 private static NinjaHealth instance;private BukkitTask task;private Method getXp;private boolean warned;private long ticks;
 public void onEnable(){instance=this;saveDefaultConfig();getServer().getPluginManager().registerEvents(this,this);task=getServer().getScheduler().runTaskTimer(this,()->{ticks++;for(Player p:getServer().getOnlinePlayers())try{if(getConfig().getBoolean("xp-health",true))maintain(p);else removeBonus(p);}catch(Exception e){if(!warned){warned=true;getLogger().severe("Native Ninja XP adapter unavailable: "+e.getClass().getSimpleName()+": "+e.getMessage());}}if(ticks%10==0)HeadBars.tick(this,getServer().getOnlinePlayers());},1L,1L);getLogger().info("NINJA_HEALTH_ENABLED: Total XP growth: +1 maximum HP per175 native Ninja XP; overhead enemy nameplates");}
 public static double ninjaXp(Player p)throws Exception {if(instance==null)throw new IllegalStateException("Plugin disabled");return instance.readXp(p);}
 private double readXp(Player p)throws Exception {Object handle=p.getClass().getMethod("getHandle").invoke(p);if(getXp==null){Class<?> c=Class.forName("net.narutomod.PlayerTracker",true,handle.getClass().getClassLoader());for(Method m:c.getMethods())if(m.getName().equals("getBattleXp")&&Modifier.isStatic(m.getModifiers())&&m.getParameterTypes().length==1&&m.getParameterTypes()[0].isInstance(handle)&&m.getReturnType()==double.class){getXp=m;break;}if(getXp==null)throw new NoSuchMethodException("PlayerTracker.getBattleXp");}if(!getXp.getParameterTypes()[0].isInstance(handle))throw new IllegalStateException("Native player provider changed");double xp=((Number)getXp.invoke(null,handle)).doubleValue();if(!Double.isFinite(xp)||xp<0)throw new IllegalStateException("Invalid native Ninja XP");return xp;}
 public static boolean maintain(Player p)throws Exception {if(instance==null||!instance.getConfig().getBoolean("xp-health",true)||!Bukkit.isPrimaryThread()||p==null||!p.isOnline()||p.isDead()||Bukkit.getPlayer(p.getUniqueId())!=p)return false;double xp=instance.readXp(p);double wanted=Math.floor(xp/175D);AttributeInstance a=p.getAttribute(Attribute.GENERIC_MAX_HEALTH);if(a==null)throw new IllegalStateException("Maximum health attribute absent");AttributeModifier old=null;double nativeBonus=0;for(AttributeModifier m:a.getModifiers()){if(BONUS.equals(m.getUniqueId()))old=m;if(NATIVE.equals(m.getUniqueId())){if(!m.getName().equals("ninja.maxhealth")||m.getOperation()!=AttributeModifier.Operation.ADD_NUMBER||!Double.isFinite(m.getAmount()))throw new IllegalStateException("Native XP health modifier changed");nativeBonus=m.getAmount();}}wanted-=nativeBonus;if(old!=null&&old.getAmount()==wanted&&old.getOperation()==AttributeModifier.Operation.ADD_NUMBER)return true;if(old!=null)a.removeModifier(old);if(wanted!=0)a.addModifier(new AttributeModifier(BONUS,"naruto.ninja_xp_health",wanted,AttributeModifier.Operation.ADD_NUMBER));if(p.getHealth()>a.getValue())p.setHealth(a.getValue());return true;}
 private static void removeBonus(Player p){AttributeInstance a=p.getAttribute(Attribute.GENERIC_MAX_HEALTH);if(a==null)return;for(AttributeModifier m:new ArrayList<AttributeModifier>(a.getModifiers()))if(BONUS.equals(m.getUniqueId()))a.removeModifier(m);if(!p.isDead()&&p.getHealth()>a.getValue())p.setHealth(a.getValue());}
 @EventHandler public void quit(PlayerQuitEvent e){/* Modifier persists under one stable UUID; joining cannot stack it. */}
 @Override public boolean onCommand(CommandSender sender,Command cmd,String label,String[] args){if(args.length==0||args[0].equalsIgnoreCase("status")){if(!(sender instanceof Player)){sender.sendMessage("Use in game: /ninjahealth status");return true;}Player p=(Player)sender;try{maintain(p);sender.sendMessage(ChatColor.GREEN+"Native Ninja XP: "+readXp(p)+" | XP bonus: +"+(long)Math.floor(readXp(p)/175D)+" HP | Maximum HP: "+p.getAttribute(Attribute.GENERIC_MAX_HEALTH).getValue());}catch(Exception e){sender.sendMessage(ChatColor.RED+"Native XP provider unavailable; no guessed bonus applied.");}return true;}if(args.length==1&&args[0].equalsIgnoreCase("reload")&&sender.hasPermission("ninjahealth.admin")){reloadConfig();HeadBars.stop();if(!getConfig().getBoolean("xp-health",true))for(Player p:getServer().getOnlinePlayers())removeBonus(p);sender.sendMessage("Ninja Health configuration reloaded.");return true;}sender.sendMessage("/ninjahealth status | reload");return true;}
 public void onDisable(){if(task!=null)task.cancel();HeadBars.stop();HandlerList.unregisterAll((Listener)this);instance=null;}
}
